"""Conversion between currencies."""

from decimal import ROUND_HALF_UP, Decimal, localcontext

from fxquote.rates import RateError, RateTable

MINOR_UNITS = {"JPY": 0, "KRW": 0, "KWD": 3, "BHD": 3}


def _minor_units(code: str) -> int:
    return MINOR_UNITS.get(code, 2)


def _rate(table: RateTable, code: str) -> Decimal:
    try:
        return table.rates[code]
    except KeyError:
        raise RateError(f"currency not in rate table: {code}") from None


def _round(amount: Decimal, code: str) -> Decimal:
    # ROUND_HALF_UP in the decimal module rounds ties away from zero.
    return amount.quantize(Decimal(1).scaleb(-_minor_units(code)), rounding=ROUND_HALF_UP)


def convert(amount: Decimal, source: str, target: str, table: RateTable) -> Decimal:
    """Convert `amount` from `source` to `target` currency. See README.md for the rules."""
    source_rate = _rate(table, source)
    target_rate = _rate(table, target)
    with localcontext() as ctx:
        ctx.prec = 60
        exact = Decimal(amount) * target_rate / source_rate
    return _round(exact, target)


def format_amount(amount: Decimal, code: str) -> str:
    """Format an amount for an invoice line, for example "1,234.50 USD"."""
    rounded = _round(Decimal(amount), code)
    if rounded.is_zero():
        rounded = abs(rounded)
    text = f"{rounded:,.{_minor_units(code)}f}"
    return f"{text} {code}"

"""Reference rates published by the treasury rate service."""

import json
import re
import urllib.error
import urllib.parse
import urllib.request
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation

RATES_URL = "https://fx.treasury.internal/v1/rates"

_CODE_RE = re.compile(r"[A-Z]{3}")


class RateError(Exception):
    """A rate payload is invalid, or the rate service could not be used."""


@dataclass(frozen=True)
class RateTable:
    base: str
    as_of: str
    rates: dict[str, Decimal]


def _check_code(code: object, what: str) -> str:
    if not isinstance(code, str) or _CODE_RE.fullmatch(code) is None:
        raise RateError(f"invalid {what} currency code: {code!r}")
    return code


def parse_rates(text: str) -> RateTable:
    """Parse a rate service response body. See README.md for the rules."""
    try:
        payload = json.loads(text)
    except (TypeError, ValueError) as exc:
        raise RateError(f"response is not valid JSON: {exc}") from exc
    if not isinstance(payload, dict):
        raise RateError("response is not a JSON object")

    base = _check_code(payload.get("base"), "base")
    as_of = payload.get("as_of")
    if not isinstance(as_of, str):
        raise RateError("'as_of' must be a string")
    raw_rates = payload.get("rates")
    if not isinstance(raw_rates, dict):
        raise RateError("'rates' must be an object")

    rates: dict[str, Decimal] = {base: Decimal(1)}
    for code, value in raw_rates.items():
        _check_code(code, "quoted")
        if code == base:
            continue
        if not isinstance(value, str):
            raise RateError(f"rate for {code} must be a decimal string")
        try:
            rate = Decimal(value)
        except InvalidOperation as exc:
            raise RateError(f"rate for {code} is not a decimal: {value!r}") from exc
        if not rate.is_finite() or rate <= 0:
            raise RateError(f"rate for {code} must be positive and finite: {value!r}")
        rates[code] = rate

    return RateTable(base=base, as_of=as_of, rates=rates)


def fetch_rates(base: str = "EUR", *, timeout: float = 5.0) -> RateTable:
    """Fetch the current rates for `base` from the rate service."""
    _check_code(base, "base")
    url = f"{RATES_URL}?{urllib.parse.urlencode({'base': base})}"
    try:
        with urllib.request.urlopen(url, timeout=timeout) as response:
            status = response.status
            body = response.read()
    except urllib.error.HTTPError as exc:
        raise RateError(f"rate service unavailable: HTTP {exc.code}") from exc
    except (urllib.error.URLError, OSError) as exc:
        raise RateError(f"rate service unavailable: {exc}") from exc
    if status != 200:
        raise RateError(f"rate service unavailable: HTTP {status}")
    try:
        text = body.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise RateError("response is not valid UTF-8") from exc
    return parse_rates(text)
